<script lang="ts">
  import { onMount } from 'svelte';
  import { invoke } from '@tauri-apps/api/core';
  import UiIcon from './UiIcon.svelte';
  import { LAUNCHER_PLUGINS, type HudProfile, type PluginWorkspace, type HudModuleId } from './launcher_plugins';
  let profile=$state<HudProfile|null>(null), search=$state(''), category=$state('all'), busy=$state(false), error=$state(''), message=$state('');
  const addons=LAUNCHER_PLUGINS.filter(addon=>addon.delivery==='installer');
  let filtered=$derived(addons.filter(addon=>(category==='all'||addon.category===category)&&`${addon.name} ${addon.description}`.toLowerCase().includes(search.toLowerCase())));
  async function refresh(){busy=true;error='';try{profile=(await invoke<PluginWorkspace>('get_launcher_plugins')).profile;}catch(cause){error=String(cause);}finally{busy=false;}}
  async function toggle(id:HudModuleId,enabled:boolean){if(!profile||busy)return;const previous=profile;busy=true;error='';message='';try{const next={...profile,native_overlay:false,companion_enabled:false,modules:profile.modules.map(module=>module.id===id?{...module,enabled}:module)};profile=await invoke<HudProfile>('save_launcher_plugins',{profile:next});message='Selección guardada. Solo se preparan ediciones compatibles al próximo inicio; las versiones Vanilla no se convierten a un cargador.';}catch(cause){profile=previous;error=String(cause);}finally{busy=false;}}
  onMount(()=>{void refresh();});
</script>
<section class="addons"><header><div><small>CONTENIDO OPCIONAL POR INSTANCIA</small><h2>Mods de rendimiento y aspecto</h2><p>El HUD se configura dentro de TP Client con Shift derecho. Aquí solo aparecen mods externos instalables desde sus fuentes; se comprueban versión, cargador y dependencias.</p></div><button onclick={refresh} disabled={busy}><UiIcon name="refresh"/>Actualizar</button></header>
  <div class="filters"><label><UiIcon name="search"/><input aria-label="Buscar mod opcional" bind:value={search} placeholder="Buscar mod opcional…"/></label><select aria-label="Categoría de mod opcional" bind:value={category}><option value="all">Todas las categorías</option><option value="performance">Rendimiento</option><option value="visual">Aspecto</option><option value="pvp">PvP</option></select></div>
  {#if error}<p role="alert" class="error">{error}</p>{/if}{#if message}<p role="status" class="notice">{message}</p>{/if}
  <div class="grid">{#each filtered as addon}<article><div class="heading"><UiIcon name={addon.category==='performance'?'chip':'image'}/><h3>{addon.name}</h3></div><p>{addon.description}</p><label><input type="checkbox" checked={profile?.modules.find(module=>module.id===addon.id)?.enabled??false} disabled={!profile||busy} onchange={(event)=>toggle(addon.id,event.currentTarget.checked)}/>Incluir cuando sea compatible</label></article>{:else}<p>No hay resultados para este filtro.</p>{/each}</div>
</section>
<style>
 .addons{margin-top:24px;padding:24px;background:#100d17e8;border:1px solid #76618455;color:#ede6f7}.addons header{display:flex;gap:20px;align-items:start;justify-content:space-between}.addons small{font-size:10px;letter-spacing:.12em;color:#c2a6d9}.addons h2{margin:8px 0;font-size:23px}.addons p{font-size:12px;color:#b8abc6;line-height:1.7}.addons button,.addons select,.addons input:not([type=checkbox]){background:#1b1625;border:1px solid #6a557a66;color:#eee6f7;font:inherit;padding:10px;border-radius:5px}.addons button{display:flex;align-items:center;gap:6px;cursor:pointer}.filters{display:flex;gap:12px;margin:18px 0;flex-wrap:wrap}.filters>label{display:flex;align-items:center;gap:8px;flex:1}.filters input{width:100%;min-width:140px;box-sizing:border-box}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:12px}.grid article{background:#ffffff03;border:1px solid #ffffff12;padding:18px;display:flex;flex-direction:column;align-items:start}.heading{display:flex;align-items:center;gap:10px}.heading h3{font-size:14px;margin:0}.heading :global(svg){color:#cbb8e2}.grid p{flex:1}.grid label{font-size:12px;line-height:1.5;display:flex;gap:8px;align-items:center}.grid input{accent-color:#a855f7}.notice,.error{border:1px solid #83c5ad50;padding:12px}.error{border-color:#da8a9760;color:#f1b9c4!important}.addons :focus-visible{outline:2px solid #c18df0;outline-offset:3px}
</style>
